"""Only load phase artifacts generated by this server for this exact dataset."""
import json


def predict_phase_for_dataset(row, dataset, registry):
    unavailable = {'status': 'unavailable', 'reported_phase': row.get('phase'), 'predicted_phase': None,
                   'class_probabilities': None, 'reason': 'Run a phase experiment on this dataset first.'}
    if dataset['is_fixture']:
        return {**unavailable, 'reason': 'Software-test fixtures cannot support phase predictions.'}
    resolver = getattr(registry, 'approved_model_resolver', None)
    if resolver is not None:
        try:
            from src.clinical_trial_intelligence.phase_model import predict_phase
            approved = resolver(task='phase')
            result = predict_phase(row, approved['directory'])
            if result.get('status') == 'available':
                return {**result, 'approved_model_id': approved['id'],
                        'artifact_sha256': approved['model']['artifact_sha256'],
                        'approval_scope': 'research_only'}
        except Exception:
            pass
        return {**unavailable, 'reason': 'No compatible approved saved phase model is available. An owner must review the model registry.'}
    for run in registry.list_experiments(dataset['id']):
        if run.get('task') != 'phase' or run['status'] != 'completed' or run.get('dataset_sha256') != dataset['sha256']:
            continue
        try:
            folder = registry.artifact_path(run['id'])
            manifest_path, model_path = folder / 'phase_manifest.json', folder / 'phase_models.joblib'
            if folder.is_symlink() or folder.resolve().parent != (registry.root / 'experiments').resolve():
                continue
            if manifest_path.is_symlink() or model_path.is_symlink():
                continue
            manifest = json.loads(manifest_path.read_text(encoding='utf-8'))
            source = manifest.get('source_metadata', {})
            if source.get('dataset_id') != dataset['id'] or source.get('sha256') != dataset['sha256']:
                continue
            from src.clinical_trial_intelligence.phase_model import predict_phase
            result = predict_phase(row, folder)
            if result.get('status') == 'available':
                return result
        except Exception:
            continue
    return unavailable
